"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { formatTime } from "../lib/date";
import {
  type ScheduleEvent,
  type ScheduleResource,
  countBookable,
  groupByResource,
} from "../lib/schedule";

export interface ResourceColumnsProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Kolommen: artsen, kamers, monteurs … */
  resources: ScheduleResource[];
  events: ScheduleEvent[];
  /** Lege kolommen krimpen tot een smalle rail met alleen de naam. */
  collapseEmpty?: boolean;
  /** Minimale breedte van een kolom voordat er horizontaal gescrold wordt. */
  minColumnWidth?: number;
  /** Maximale hoogte van de lijst in een kolom. */
  maxHeight?: number | string;
  emptyLabel?: React.ReactNode;
  /** Tekst achter het aantal, bv. "afspraken". */
  countLabel?: string;
  onEventClick?: (event: ScheduleEvent) => void;
  /** Knoppen rechts in de kolomkop. */
  renderResourceActions?: (resource: ScheduleResource) => React.ReactNode;
  /** Knoppen rechts in een rij. */
  renderEventActions?: (event: ScheduleEvent) => React.ReactNode;
  /** Eigen inhoud voor een rij. */
  renderEvent?: (event: ScheduleEvent) => React.ReactNode;
}

/**
 * ResourceColumns — de klassieke dagagenda: één kolom per arts of kamer, met
 * daarin een lijst van tijd, status en naam. Met `collapseEmpty` schuiven
 * kolommen zonder afspraken samen tot een smalle rail, zodat de drukke kolommen
 * alle ruimte krijgen.
 */
export const ResourceColumns = React.forwardRef<HTMLDivElement, ResourceColumnsProps>(
  function ResourceColumns(
    {
      resources,
      events,
      collapseEmpty,
      minColumnWidth = 230,
      maxHeight = 460,
      emptyLabel = "Geen afspraken",
      countLabel = "afspraken",
      onEventClick,
      renderResourceActions,
      renderEventActions,
      renderEvent,
      className,
      ...rest
    },
    ref
  ) {
    const byResource = React.useMemo(() => groupByResource(events, resources), [events, resources]);

    return (
      <div ref={ref} className={cn("pxui-rescols", className)} {...rest}>
        {resources.map((resource) => {
          const list = byResource.get(resource.key) ?? [];
          const empty = list.length === 0;
          const collapsed = Boolean(collapseEmpty && empty);

          if (collapsed) {
            return (
              <div className="pxui-rescol pxui-rescol-collapsed" key={resource.key}>
                <div className="pxui-rescol-rail">
                  {resource.media}
                  <span className="pxui-rescol-rail-label">{resource.label} · vrij</span>
                </div>
              </div>
            );
          }

          return (
            <div
              className="pxui-rescol"
              key={resource.key}
              style={{ minWidth: minColumnWidth }}
              data-today={resource.today ? "" : undefined}
            >
              <div className="pxui-rescol-head">
                {resource.media && <span className="pxui-rescol-media">{resource.media}</span>}
                <div className="pxui-rescol-info">
                  <div className="pxui-rescol-name">{resource.label}</div>
                  <div className="pxui-rescol-count">
                    {resource.sublabel ?? `${countBookable(list)} ${countLabel}`}
                  </div>
                </div>
                {renderResourceActions && (
                  <div className="pxui-rescol-actions">{renderResourceActions(resource)}</div>
                )}
              </div>

              <div className="pxui-rescol-list" style={{ maxHeight }}>
                {empty ? (
                  <div className="pxui-rescol-empty">{emptyLabel}</div>
                ) : (
                  list.map((event) =>
                    event.blocked ? (
                      <div className="pxui-rescol-blocked" key={event.id}>
                        <span className="pxui-rescol-time">{formatTime(event.start)}</span>
                        <span className="pxui-rescol-blocked-label">{event.title}</span>
                      </div>
                    ) : (
                      <div
                        key={event.id}
                        role={onEventClick ? "button" : undefined}
                        tabIndex={onEventClick ? 0 : undefined}
                        className={cn("pxui-rescol-row", onEventClick && "pxui-rescol-row-clickable")}
                        onClick={() => onEventClick?.(event)}
                        onKeyDown={(keyEvent) => {
                          if (keyEvent.key === "Enter" || keyEvent.key === " ") {
                            keyEvent.preventDefault();
                            onEventClick?.(event);
                          }
                        }}
                      >
                        {renderEvent ? (
                          renderEvent(event)
                        ) : (
                          <>
                            <span className="pxui-rescol-time">{formatTime(event.start)}</span>
                            <span
                              className={cn("pxui-rescol-dot", `pxui-tone-${event.tone ?? "neutral"}`)}
                              style={event.color ? { background: event.color } : undefined}
                            />
                            <span className="pxui-rescol-title">
                              {event.title}
                              {event.subtitle && (
                                <span className="pxui-rescol-sub">{event.subtitle}</span>
                              )}
                            </span>
                          </>
                        )}
                        {renderEventActions && (
                          <span
                            className="pxui-rescol-row-actions"
                            onClick={(clickEvent) => clickEvent.stopPropagation()}
                          >
                            {renderEventActions(event)}
                          </span>
                        )}
                      </div>
                    )
                  )
                )}
              </div>
            </div>
          );
        })}
      </div>
    );
  }
);

/* ============================ ResourceColumns ============================ */
.pxui-rescols {
  display: flex; align-items: stretch; gap: 12px;
  overflow-x: auto; -webkit-overflow-scrolling: touch;
  padding-bottom: 4px; min-width: 0;
}

.pxui-rescol {
  flex: 1 1 0; min-width: 0;
  display: flex; flex-direction: column;
  background: var(--surface); border: 1px solid var(--border);
  border-radius: var(--r-lg); box-shadow: var(--sh-sm); overflow: hidden;
}
.pxui-rescol[data-today] { border-color: var(--accent-border); }

/* ---------- Ingeklapte, lege kolom ---------- */
.pxui-rescol-collapsed {
  flex: 0 0 54px; min-width: 54px;
  background: var(--surface-2); border-style: dashed;
}
.pxui-rescol-rail {
  flex: 1; display: flex; flex-direction: column; align-items: center; gap: 12px;
  padding: 14px 0;
}
.pxui-rescol-rail-label {
  writing-mode: vertical-rl; text-orientation: mixed;
  font-size: 12px; font-weight: 600; color: var(--text-3); white-space: nowrap;
}

/* ---------- Kop ---------- */
.pxui-rescol-head {
  display: flex; align-items: center; gap: 10px;
  padding: 11px 13px; border-bottom: 1px solid var(--border);
  background: var(--surface-2);
}
.pxui-rescol-media { flex: none; display: flex; }
.pxui-rescol-info { flex: 1; min-width: 0; }
.pxui-rescol-name {
  font-size: 13.5px; font-weight: 650; color: var(--text);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.pxui-rescol-count { font-size: 11.5px; color: var(--text-3); margin-top: 1px; }
.pxui-rescol-actions { flex: none; display: flex; gap: 4px; }

/* ---------- Lijst ---------- */
.pxui-rescol-list { overflow-y: auto; overscroll-behavior: contain; padding: 5px; }
.pxui-rescol-empty {
  padding: 26px 12px; text-align: center;
  font-size: 12.5px; color: var(--text-3); font-style: italic;
}

.pxui-rescol-row {
  display: flex; align-items: center; gap: 9px;
  padding: calc(8px * var(--density)) 9px; border-radius: var(--r-sm); min-width: 0;
  transition: background var(--dur-fast);
}
.pxui-rescol-row + .pxui-rescol-row { margin-top: 2px; }
.pxui-rescol-row-clickable { cursor: pointer; }
.pxui-rescol-row-clickable:hover { background: var(--surface-hover); }
.pxui-rescol-row-clickable:focus-visible { outline: none; box-shadow: var(--ring); }

.pxui-rescol-time {
  flex: none; width: 42px;
  font-size: 12px; font-weight: 650; color: var(--text-2);
  font-variant-numeric: tabular-nums;
}
.pxui-rescol-dot {
  flex: none; width: 8px; height: 8px; border-radius: var(--r-full);
  background: var(--text-3);
}
.pxui-rescol-title {
  flex: 1; min-width: 0; display: flex; flex-direction: column;
  font-size: 13px; font-weight: 550; color: var(--text);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.pxui-rescol-sub { font-size: 11.5px; font-weight: 400; color: var(--text-3); }
.pxui-rescol-row-actions { flex: none; display: flex; gap: 3px; opacity: 0; transition: opacity var(--dur-fast); }
.pxui-rescol-row:hover .pxui-rescol-row-actions,
.pxui-rescol-row:focus-within .pxui-rescol-row-actions { opacity: 1; }

/* ---------- Geblokkeerd ---------- */
.pxui-rescol-blocked {
  display: flex; align-items: center; gap: 9px;
  padding: 8px 9px; border-radius: var(--r-sm); margin-top: 2px;
  background-image: repeating-linear-gradient(
    -45deg,
    var(--red-tint) 0,
    var(--red-tint) 4px,
    var(--surface) 4px,
    var(--surface) 9px
  );
  border: 1px solid color-mix(in srgb, var(--red) 22%, transparent);
}
.pxui-rescol-blocked .pxui-rescol-time { color: var(--red); }
.pxui-rescol-blocked-label { font-size: 12.5px; font-weight: 600; color: var(--red); }

/* ---------- Statuskleuren, gedeeld met de andere agendaweergaven ---------- */
.pxui-tone-accent { background: var(--accent); }
.pxui-tone-green { background: var(--green); }
.pxui-tone-amber { background: var(--amber); }
.pxui-tone-red { background: var(--red); }
.pxui-tone-blue { background: var(--blue); }
.pxui-tone-violet { background: var(--violet); }
.pxui-tone-neutral { background: var(--text-3); }

import type * as React from "react";

/**
 * Gedeeld datamodel voor alle agendaweergaven.
 *
 * WeekSchedule, ResourceColumns, Swimlanes en TimeSlotList werken op precies
 * dezelfde gegevens, zodat je met één knop van weergave kunt wisselen zonder
 * je data om te bouwen.
 */

export type ScheduleTone = "accent" | "green" | "amber" | "red" | "blue" | "violet" | "neutral";

/** Een kolom of rij in de agenda: een dag, een arts, een kamer, een machine. */
export interface ScheduleResource {
  /** Unieke sleutel; events verwijzen hiernaar. */
  key: string;
  label: React.ReactNode;
  /** Tweede regel, bv. het dagnummer of het aantal afspraken. */
  sublabel?: React.ReactNode;
  /** Avatar of icoon links van het label. */
  media?: React.ReactNode;
  /** Eigen kleur voor deze resource (koptekst, tag, blokken zonder eigen kleur). */
  color?: string;
  /** Markeert deze kolom als vandaag. */
  today?: boolean;
  /** Hele kolom gearceerd, bv. een sluitingsdag of afwezigheid. */
  blocked?: boolean;
  blockedLabel?: React.ReactNode;
}

export interface ScheduleEvent {
  id: string;
  /** Sleutel van de resource (dag, arts, kamer …) waar dit item bij hoort. */
  resource: string;
  /** Begin in minuten sinds middernacht (09:30 = 570). */
  start: number;
  /** Einde in minuten sinds middernacht. */
  end: number;
  title: React.ReactNode;
  subtitle?: React.ReactNode;
  tone?: ScheduleTone;
  /** Eigen kleur; overschrijft `tone` en de kleur van de resource. */
  color?: string;
  /** Kan niet versleept of aangepast worden. */
  locked?: boolean;
  /** Geblokkeerde tijd: gearceerd, nooit versleepbaar, geen klikactie. */
  blocked?: boolean;
  /** Vrij veld voor je eigen gegevens. */
  meta?: unknown;
}

/** Positie van een event wanneer overlappende items naast elkaar staan. */
export interface LaidOutEvent<T extends { start: number; end: number }> {
  event: T;
  /** Kolomindex binnen de groep overlappende items. */
  lane: number;
  /** Aantal kolommen in die groep. */
  lanes: number;
}

/**
 * Legt overlappende items naast elkaar: items die elkaar raken vormen een
 * cluster en krijgen daarbinnen elk een eigen kolom.
 */
export function packLanes<T extends { start: number; end: number }>(items: T[]): Array<LaidOutEvent<T>> {
  const sorted = [...items].sort((a, b) => a.start - b.start || a.end - b.end);
  const result: Array<LaidOutEvent<T>> = [];

  let cluster: T[] = [];
  let clusterEnd = -1;

  const flush = () => {
    if (cluster.length === 0) return;
    const laneEnds: number[] = [];
    const placed = cluster.map((event) => {
      let lane = laneEnds.findIndex((end) => end <= event.start);
      if (lane === -1) {
        lane = laneEnds.length;
        laneEnds.push(event.end);
      } else {
        laneEnds[lane] = event.end;
      }
      return { event, lane };
    });
    for (const entry of placed) result.push({ ...entry, lanes: laneEnds.length });
    cluster = [];
    clusterEnd = -1;
  };

  for (const event of sorted) {
    if (cluster.length > 0 && event.start >= clusterEnd) flush();
    cluster.push(event);
    clusterEnd = Math.max(clusterEnd, event.end);
  }
  flush();

  return result;
}

/** Groepeert events per resource, in de volgorde van de resources zelf. */
export function groupByResource<T extends { resource: string }>(
  events: T[],
  resources: Array<{ key: string }>
): Map<string, T[]> {
  const map = new Map<string, T[]>();
  for (const resource of resources) map.set(resource.key, []);
  for (const event of events) {
    const list = map.get(event.resource);
    if (list) list.push(event);
  }
  for (const list of map.values()) {
    list.sort((a, b) => ((a as { start?: number }).start ?? 0) - ((b as { start?: number }).start ?? 0));
  }
  return map;
}

/** Groepeert events per starttijd, oplopend — de basis voor een tijdlijn. */
export function groupByStart<T extends { start: number }>(events: T[]): Array<{ start: number; events: T[] }> {
  const map = new Map<number, T[]>();
  for (const event of events) {
    const list = map.get(event.start) ?? [];
    list.push(event);
    map.set(event.start, list);
  }
  return [...map.entries()]
    .sort((a, b) => a[0] - b[0])
    .map(([start, list]) => ({ start, events: list }));
}

/** Telt de items die echt een afspraak zijn (geblokkeerde tijd niet meegerekend). */
export function countBookable(events: Array<{ blocked?: boolean }>): number {
  return events.filter((event) => !event.blocked).length;
}

/** De kleur van een event: eigen kleur, anders die van de resource, anders de toon. */
export function eventColor(
  event: { color?: string; tone?: ScheduleTone },
  resource?: { color?: string }
): string | undefined {
  return event.color ?? resource?.color;
}

/** Huidige tijd in minuten sinds middernacht. */
export function nowMinutes(): number {
  const date = new Date();
  return date.getHours() * 60 + date.getMinutes();
}
